-- =====================================================================
-- DASHBOARD DEMO DATA (generated)
--
-- Fills devitostyles with about a year of realistic history so the admin
-- dashboard has something to show: demo customers, appointments, product
-- orders, payments and reviews. Dates are relative to the day you run it.
--
-- Every row belongs to a customer whose email ends in @demo.devitostyles.com,
-- so it can be removed again with sql/remove-dashboard-demo-data.sql.
-- Running this script again first clears the previous demo data.
-- Demo customers cannot log in (their password is not a valid hash).
-- =====================================================================

USE devitostyles;

-- Clear any previous demo data
SET @demo_email = '%@demo.devitostyles.com';

DELETE r FROM review r
    JOIN users u ON u.user_id = r.user_id
    WHERE u.email LIKE @demo_email;

DELETE a FROM appointment a
    JOIN users u ON u.user_id = a.user_id
    WHERE u.email LIKE @demo_email;

DELETE p FROM payments p
    JOIN orders o ON o.order_id = p.order_id
    JOIN users u ON u.user_id = o.user_id
    WHERE u.email LIKE @demo_email;

DELETE oi FROM order_items oi
    JOIN orders o ON o.order_id = oi.order_id
    JOIN users u ON u.user_id = o.user_id
    WHERE u.email LIKE @demo_email;

DELETE o FROM orders o
    JOIN users u ON u.user_id = o.user_id
    WHERE u.email LIKE @demo_email;

DELETE ci FROM cart_items ci
    JOIN carts c ON c.cart_id = ci.cart_id
    JOIN users u ON u.user_id = c.user_id
    WHERE u.email LIKE @demo_email;

DELETE c FROM carts c
    JOIN users u ON u.user_id = c.user_id
    WHERE u.email LIKE @demo_email;

DELETE FROM users WHERE email LIKE @demo_email;

